mapper.select:
SELECT C.*, SC.SaleCompName AS SaleCompName, CP.ChnlPolicyName AS ChnlPolicyName
FROM shopwizard.tCmpChnl C
LEFT OUTER JOIN shopwizard.tCmpSaleComp SC ON C.SaleCompCode = SC.SaleCompCode
LEFT OUTER JOIN shopwizard.tCmpChnlPolicy CP ON C.ChnlPolicyCode = CP.ChnlPolicyCode

    AND C.SvcCode = #{pSvcCode}
    AND C.ChnlCode = #{pChnlCode}
    AND C.ChnlName LIKE CONCAT('%',#{pChnlName},'%')
    AND C.SaleCompCode = #{pSaleCompCode}
    AND C.State = #{pState}
    AND C.AdjustPeriodCode = #{pAdjustPeriodCode}
    AND C.MngrMd = #{pMngrMd}


    ORDER BY ${sidx} ${sord}
    ORDER BY C.ChnlName

LIMIT #{pPageOffset}, #{pPageSize}

SELECT COUNT(*)
FROM shopwizard.tCmpChnl C
INNER JOIN shopwizard.tCmpSaleComp SC ON C.SaleCompCode = SC.SaleCompCode
INNER JOIN shopwizard.tCmpChnlPolicy CP ON C.ChnlPolicyCode = CP.ChnlPolicyCode

    AND C.SvcCode = #{pSvcCode}
    AND C.ChnlCode = #{pChnlCode}
    AND C.ChnlName LIKE CONCAT('%',#{pChnlName},'%')
    AND C.SaleCompCode = #{pSaleCompCode}
    AND C.State = #{pState}
    AND C.AdjustPeriodCode = #{pAdjustPeriodCode}
    AND C.MngrMd = #{pMngrMd}

SELECT MAX(ChnlCode)
FROM shopwizard.tCmpChnl
WHERE SaleCompCode = #{value}
